import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createBedrockProvider} from '../providers/bedrock/bedrockProvider.js';
import type {ChatSession} from '../types/session.js';

describe('beforeSession failure', () => {
  // specs/hal-engine-config-hooks/spec.md#7
  it('reports the original error and runs cleanup before rejecting', async () => {
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    const failure = new Error('allocation failed');
    const calls: unknown[][] = [];
    const orchestrator = createChatOrchestrator(
      createBedrockProvider({type: 'bedrock', region: 'eu-west-1', modelId: 'model', maxTokens: 16}),
      new PromptBuilder({identity: 'Assistant'}),
      undefined,
      {
        hooks: {
          beforeSession: async received => {
            calls.push(['beforeSession', received]);
            throw failure;
          },
          beforeUserInput: async (_session, message) => {
            calls.push(['beforeUserInput']);
            return message;
          },
          onError: async (received, error) => void calls.push(['onError', received, error]),
          afterSession: async received => void calls.push(['afterSession', received]),
        },
      }
    );

    const outcome = await orchestrator.processMessage(session).catch((error: unknown) => error);

    expect({outcome, calls}).toEqual({
      outcome: failure,
      calls: [
        ['beforeSession', session],
        ['onError', session, failure],
        ['afterSession', session],
      ],
    });
  });
});
EOF
cat > .lore/dod.md <<'EOF'
# Definition of Done

> "'`beforeSession` is awaited before the `try` block opens, so a throw from it escapes before the `catch` and `finally` exist. Neither `onError` nor `afterSession` runs.

**Strategy: `direct`** — `createChatOrchestrator` exposes the lifecycle hooks and the caller'"'s rejection directly. A real provider can be supplied without contacting it because the failing hook runs first.

## Done when these pass

- [ ] **reports the original error and runs cleanup before rejecting** — A failed "'`beforeSession` reaches `onError` with the session and original error, then `afterSession`, before the same error reaches the caller; later turn hooks have not run.
  `src/orchestration/chatOrchestrator.acceptance.test.ts`

## Facets

- [ ] Move `beforeSession` into the existing error and cleanup boundary while preserving the original rejection and successful hook behavior.
- [ ] Replace the recorded flaw in the spec with the guarantee, explaining that cleanup can follow a failed setup before the turn proceeds.
- [ ] Describe the consumer-visible hook change in the changelog and keep the existing tests unedited.
- [ ] Pass the ticket'"'s CI checks.

## Out of scope

- Non-Error throws and usage accounting across tool rounds.
EOF
